mapper.select:
SELECT mn.*,pro.P_Name AS projectName, con.Con_Name AS contractName, com.C_Name AS constructionUnitName FROM Project_Acceptance_Settlement mn LEFT JOIN pre_project pro ON mn.project_id = pro.P_ID LEFT JOIN con_contract con ON mn.contract_id = con.Con_Id LEFT JOIN sys_company com ON mn.construction_unit = com.C_ID
AND mn.project_id = #{params.projectId}
AND likePname(#{params.projectName},pro.P_Id)=true
AND pro.P_Name like concat('%',#{params.projectName},'%')
AND mn.project_type = #{params.projectType}
AND mn.construction_unit = #{params.constructionUnit}
AND likeCname(#{params.constructionUnitName},com.C_Id)=true
AND com.C_Name like concat('%',#{params.constructionUnitName},'%')
AND mn.contract_id = #{params.contractId}
AND con.Con_Name like concat('%',#{params.contractName},'%')
AND mn.project_name_temp like concat('%',#{params.projectNameTemp},'%')
